//! Compile check for the Rust generator's emitted output: each committed golden is
//! generated code (see rust/rustgen-golden/README or tests/test_rustgen.cpp), included
//! under its own module so a schema's `arena`/`common` trees are siblings, matching how
//! a consumer includes one schema's generated file. Generated by the `[rustgen-golden]`
//! test from the no-import corpus; regenerate with tests/regen_goldens.sh.
//!
//! A file must be included at the module path it was generated for. This one has no
//! references between its types, so only its generated check can reject a wrong path:
//!
//! ```compile_fail
//! mod elsewhere {
//!     include!(concat!(env!("CARGO_MANIFEST_DIR"), "/goldens/streamonly_flat.rs"));
//! }
//! fn main() {}
//! ```
//!
//! A module named like the check does not hide a wrong path:
//!
//! ```compile_fail
//! mod streamonly_flat {
//!     mod rp_check {
//!         include!(concat!(env!("CARGO_MANIFEST_DIR"), "/goldens/streamonly_flat.rs"));
//!     }
//! }
//! fn main() {}
//! ```
//!
//! The same file at its own path compiles:
//!
//! ```
//! mod streamonly_flat {
//!     include!(concat!(env!("CARGO_MANIFEST_DIR"), "/goldens/streamonly_flat.rs"));
//! }
//! fn main() {}
//! ```
#![cfg_attr(not(feature = "std"), no_std)]
// A crate that denies `unused` must be able to include generated code. The `extern crate`
// below is this crate's own, not generated.
#![deny(unused)]
#![allow(unused_extern_crates)]
// Generated code names every prelude item by its full path, since a schema type
// (`Option`, `Result`) or a caller's macro (`matches!`) can shadow the bare name: without
// the prelude, an unqualified use fails to compile here.
#![no_implicit_prelude]

// Generated code must also compile in a crate that declares the runtime this way.
extern crate rapidproto;

